use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/control-codegen175";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-29-control-codegen175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let root=Path::new(R);let dest=Path::new(D);assert!(!dest.exists());let art=dest.join("artifacts");fs::create_dir_all(&art).unwrap();let names=["audit.rs","text-differences.rs","function-differences.rs","literal-review.rs","publish.rs","analysis.json","text-differences.json","function-differences.json","literal-review.json","grouping-accepted-normalized.asm","grouping-OFF-normalized.asm"];for name in names{fs::copy(root.join(name),art.join(name)).unwrap();}
let mut records=BTreeMap::new();for e in fs::read_dir(root).unwrap(){let p=e.unwrap().path();if !p.is_file()||!p.extension().is_some_and(|e|["rs","json","asm","txt","log"].contains(&e.to_str().unwrap())){continue}let b=fs::read(&p).unwrap();let text=String::from_utf8(b.clone()).unwrap();records.insert(p.file_name().unwrap().to_str().unwrap().to_string(),json!({"sha256":hash(&p),"length":b.len(),"utf8":text}));}let b=serde_json::to_vec(&records).unwrap();let temp=root.join("archive-input.json");assert!(!temp.exists());fs::write(&temp,&b).unwrap();let out=art.join("static-evidence.json.gz");let f=fs::File::create(&out).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&temp).stdout(Stdio::from(f)).status().unwrap().success());let back=Command::new("gzip").arg("-dc").arg(&out).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,b);let v:Value=serde_json::from_slice(&back.stdout).unwrap();for(name,c)in v.as_object().unwrap(){assert_eq!(c["utf8"].as_str().unwrap().as_bytes(),fs::read(root.join(name)).unwrap());assert_eq!(c["sha256"],hash(root.join(name)));}fs::remove_file(temp).unwrap();fs::write(art.join("publication-review.json"),serde_json::to_vec_pretty(&json!({"members":records.len(),"archive_sha256":hash(&out),"roundtrip_byte_exact":true,"new_SDK_requests":0,"new_proofs":0,"production_changed":false})).unwrap()).unwrap();println!("Archived{} static source/evidence members byte-exact; no runtime requests",records.len());}
